-- 六项指标单脚本：海豚调度只需一个Doris/MySQL SQL节点，NON_QUERY，按本文件顺序执行。
-- 建议每小时整点运行，时区Asia/Shanghai，同一结果表并发数1；先停旧Node任务。
-- JDBC连接启用allowMultiQueries=true，遇错停止，不使用忽略错误继续执行模式。
-- 首次接管已完成，检查点保存在结果表中；本文件仅做日常增量更新，真实0保留。
-- 四项订单指标T-1，库存两项及原Skill/业务口径不变；正式结果表仍只有ai_db.order_kpi_result_v1。
-- 从库内读取增量进度，不内嵌历史检查点；新增、修改、删除和历史修正处理保持原规则。
-- 失败时正式业务数据保持上个成功批次，排查后可从文件开头重跑；只清理脚本自己的工作表。
USE ai_db;
SET time_zone='Asia/Shanghai';
SET query_timeout=1800;
SET insert_timeout=1800;


-- 01_prepare
CREATE TABLE IF NOT EXISTS ai_db.order_kpi_ds_run LIKE ai_db.order_kpi_result_v1;
CREATE TABLE IF NOT EXISTS ai_db.order_kpi_ds_delta LIKE ai_db.order_kpi_result_v1;
CREATE TABLE IF NOT EXISTS ai_db.order_kpi_ds_versions (phase VARCHAR(8) NOT NULL,source VARCHAR(128) NOT NULL,fingerprint STRING NULL) UNIQUE KEY(phase,source) DISTRIBUTED BY HASH(source) BUCKETS 1 PROPERTIES('replication_num'='1');
CREATE TABLE IF NOT EXISTS ai_db.order_kpi_ds_scan (family VARCHAR(32) NOT NULL,source VARCHAR(128) NOT NULL,`role` VARCHAR(16) NOT NULL,b INT NOT NULL,fingerprint STRING NULL) UNIQUE KEY(family,source,`role`,b) DISTRIBUTED BY HASH(family,source,b) BUCKETS 1 PROPERTIES('replication_num'='1');
CREATE TABLE IF NOT EXISTS ai_db.order_kpi_ds_dirty (family VARCHAR(32) NOT NULL,b INT NOT NULL) UNIQUE KEY(family,b) DISTRIBUTED BY HASH(family,b) BUCKETS 1 PROPERTIES('replication_num'='1');
TRUNCATE TABLE ai_db.order_kpi_ds_run;
TRUNCATE TABLE ai_db.order_kpi_ds_versions;
TRUNCATE TABLE ai_db.order_kpi_ds_scan;
TRUNCATE TABLE ai_db.order_kpi_ds_dirty;
TRUNCATE TABLE ai_db.order_kpi_ds_delta;;

-- 02_freeze_run
INSERT INTO ai_db.order_kpi_ds_run (metric_code,record_type,record_key,calculation_scope,stat_time,snapshot_date,order_no,source_order_no,line_no,customer_code,sku_code,base_name,pickup_point,item_name,category_name,director_name,region_name,province_name,sales_region,numerator,denominator,base_denominator,candidate_count,known_count,pending_count,judgement_state,pending_reason_code,pending_reason_text,quantity_unit_code,aggregation_rule_code,rule_version,data_cutoff_time,updated_at,calc_extra_json) SELECT h.metric_code AS `metric_code`,h.record_type AS `record_type`,h.record_key AS `record_key`,h.calculation_scope AS `calculation_scope`,h.stat_time AS `stat_time`,DATE_ADD(CURRENT_DATE(),INTERVAL 1 DAY) AS `snapshot_date`,CAST(h.updated_at AS STRING) AS `order_no`,UUID() AS `source_order_no`,h.line_no AS `line_no`,h.customer_code AS `customer_code`,h.sku_code AS `sku_code`,h.base_name AS `base_name`,h.pickup_point AS `pickup_point`,h.item_name AS `item_name`,h.category_name AS `category_name`,h.director_name AS `director_name`,h.region_name AS `region_name`,h.province_name AS `province_name`,h.sales_region AS `sales_region`,CAST((SELECT COUNT(*) FROM ai_db.order_kpi_result_v1) AS DECIMAL(38,12)) AS `numerator`,CAST((SELECT DATA_LENGTH FROM information_schema.tables WHERE TABLE_SCHEMA='ai_db' AND TABLE_NAME='order_kpi_result_v1') AS DECIMAL(38,12)) AS `denominator`,CAST(h.base_denominator AS DECIMAL(38,12)) AS `base_denominator`,h.candidate_count AS `candidate_count`,h.known_count AS `known_count`,h.pending_count AS `pending_count`,h.judgement_state AS `judgement_state`,h.pending_reason_code AS `pending_reason_code`,h.pending_reason_text AS `pending_reason_text`,h.quantity_unit_code AS `quantity_unit_code`,h.aggregation_rule_code AS `aggregation_rule_code`,h.rule_version AS `rule_version`,CURRENT_DATE() AS `data_cutoff_time`,NOW(6) AS `updated_at`,h.calc_extra_json AS `calc_extra_json` FROM ai_db.order_kpi_result_v1 h WHERE h.metric_code='metadata' AND h.record_type='coverage';

-- 03_contract_guard
INSERT INTO ai_db.order_kpi_ds_versions (phase,source,fingerprint) SELECT 'guard','03_contract_guard',CAST((SELECT number FROM numbers("number"="2") WHERE NOT(COALESCE(((SELECT CAST(IF((SELECT COUNT(*) FROM ai_db.order_kpi_ds_run)=1 AND (SELECT rule_version FROM ai_db.order_kpi_ds_run)=145656960853753 AND (SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.profileHash') FROM ai_db.order_kpi_ds_run)='ef51e3db85182af5611ca268d6a283954004789cb126970e586ae0cc351cd75a' AND (SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.state') FROM ai_db.order_kpi_ds_run)='complete' AND (SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.encoding') FROM ai_db.order_kpi_ds_run)='processed-compact-v2' AND (SELECT denominator FROM ai_db.order_kpi_ds_run)>0 AND (SELECT denominator FROM ai_db.order_kpi_ds_run)<8589934592 AND (SELECT numerator FROM ai_db.order_kpi_ds_run)<15500000 AND (SELECT COUNT(*) FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_source_version')=8 AND (SELECT COUNT(*) FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state')>0 AND (SELECT COUNT(*) FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state')=IF((SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.checkpointFormat') FROM ai_db.order_kpi_ds_run)='sql-family-v1',CAST((SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.sqlStateCount') FROM ai_db.order_kpi_ds_run) AS BIGINT),(SELECT candidate_count FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_bootstrap' AND source_order_no=(SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.incrementalState') FROM ai_db.order_kpi_ds_run))) AND (SELECT data_cutoff_time FROM ai_db.order_kpi_ds_run)>=CAST((SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.orderEndExclusive') FROM ai_db.order_kpi_ds_run) AS DATETIME) AND (SELECT snapshot_date FROM ai_db.order_kpi_ds_run)>=CAST((SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.inventoryEndExclusive') FROM ai_db.order_kpi_ds_run) AS DATE),1,0) AS STRING) AS gate)='1' AND (SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.checkpointFormat') FROM ai_db.order_kpi_ds_run)='sql-family-v1'),FALSE))) AS STRING);

-- 10_00_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_scm_execute_detail_d',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_scm_execute_detail_d');

-- 10_01_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_scm_execute_detail_hourly_d',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_scm_execute_detail_hourly_d');

-- 10_02_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_scm_order_trace_final_di',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_scm_order_trace_final_di');

-- 10_03_warehouse
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','dim_bas_warehouse',CONCAT(CAST(COUNT(*) AS STRING),':',CAST(SUM(CRC32(CAST(JSON_ARRAY(warehouse_id,warehouse_classify) AS STRING))) AS STRING)) FROM dim_bas_warehouse;

-- 10_04_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_scm_material_in_out_summary_d',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_scm_material_in_out_summary_d');

-- 10_05_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_order_execute_isontime_mi',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_order_execute_isontime_mi');

-- 10_06_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_scm_stock_detail_d',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_scm_stock_detail_d');

-- 10_07_save
INSERT INTO ai_db.order_kpi_ds_versions SELECT 'before','agents_dim_mark_xilie_d',GROUP_CONCAT(CONCAT(CAST(PartitionId AS STRING),':',CAST(VisibleVersion AS STRING)),',' ORDER BY PartitionId) FROM partitions('catalog'='internal','database'='ai_db','table'='agents_dim_mark_xilie_d');

-- 11_partition_guard
INSERT INTO ai_db.order_kpi_ds_versions (phase,source,fingerprint) SELECT 'guard','11_partition_guard',CAST((SELECT number FROM numbers("number"="2") WHERE NOT(COALESCE(((SELECT CAST(IF((SELECT COUNT(*) FROM ai_db.order_kpi_ds_versions WHERE phase='before')=8 AND (SELECT COUNT(*) FROM ai_db.order_kpi_ds_versions WHERE phase='before' AND fingerprint IS NULL)=0,1,0) AS STRING) AS gate)='1'),FALSE))) AS STRING);

-- 12_refresh_gate
UPDATE ai_db.order_kpi_ds_run SET candidate_count=IF(EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND NOT(v.fingerprint<=>o.calc_extra_json)) OR (SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.checkpointFormat') FROM ai_db.order_kpi_ds_run)<>'sql-family-v1' OR CAST((SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.orderEndExclusive') FROM ai_db.order_kpi_ds_run) AS DATE)<>CAST((SELECT data_cutoff_time FROM ai_db.order_kpi_ds_run) AS DATE) OR CAST((SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.inventoryEndExclusive') FROM ai_db.order_kpi_ds_run) AS DATE)<>(SELECT snapshot_date FROM ai_db.order_kpi_ds_run),1,0);

-- 20_0_fingerprints
INSERT INTO ai_db.order_kpi_ds_scan SELECT 'cancellation' family,'agents_scm_execute_detail_d' source,'groups' `role`,n.b,n.fingerprint FROM (SELECT MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) AS b,CONCAT(CAST(COUNT(*) AS STRING),'/',CAST(SUM(CAST(CONV(SUBSTR(h,1,15),16,10) AS DECIMAL(38,0))) AS STRING),'/',CAST(SUM(CAST(CONV(SUBSTR(h,16,15),16,10) AS DECIMAL(38,0))) AS STRING)) AS fingerprint FROM (SELECT `cust_code` AS cust_code,MD5(CAST(JSON_ARRAY(`cust_order_no`,`cust_code`,`material_code`,`header_addtime`,`cust_name`,`province_region_name`,`region_name`,`belong_base`,`qtyshipped`,`pickup_point`,`executeorderno`,`executeorderlineno`,`detailstatus`,`fromorderno`,`warehouseid`,`receive_wh`,`orderstatus`,`load_time`,`need_qty_origin`,`is_virtual`,`createsource`,`timeout_code`,`wms_close_time`,`canceltime`,`latestsendcardate`,`change_order_qty`,`dms_last_update_qty`,`province`,`warehouse_classify`) AS STRING)) h FROM agents_scm_execute_detail_d) x GROUP BY b) n WHERE EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_execute_detail_d' AND NOT(v.fingerprint<=>o.calc_extra_json)) UNION ALL SELECT o.family,o.source,o.`role`,o.b,o.fingerprint FROM (SELECT calculation_scope family,source_order_no source,line_no `role`,CAST(numerator AS INT) b,calc_extra_json fingerprint FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state') o WHERE o.family='cancellation' AND o.source='agents_scm_execute_detail_d' AND o.`role`='groups' AND NOT(EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_execute_detail_d' AND NOT(v.fingerprint<=>o.calc_extra_json)))
UNION ALL
SELECT 'cancellation' family,'agents_scm_execute_detail_hourly_d' source,'groups' `role`,n.b,n.fingerprint FROM (SELECT MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) AS b,CONCAT(CAST(COUNT(*) AS STRING),'/',CAST(SUM(CAST(CONV(SUBSTR(h,1,15),16,10) AS DECIMAL(38,0))) AS STRING),'/',CAST(SUM(CAST(CONV(SUBSTR(h,16,15),16,10) AS DECIMAL(38,0))) AS STRING)) AS fingerprint FROM (SELECT `cust_code` AS cust_code,MD5(CAST(JSON_ARRAY(`cust_order_no`,`cust_code`,`material_code`,`header_addtime`,`cust_name`,`province_region_name`,`region_name`,`belong_base`,`qtyshipped`,`pickup_point`,`executeorderno`,`executeorderlineno`,`detailstatus`,`fromorderno`,`warehouseid`,`receive_wh`,`orderstatus`,`load_time`,`need_qty_origin`,`is_virtual`,`createsource`,`timeout_code`,`wms_close_time`,`canceltime`,`latestsendcardate`,`change_order_qty`,`dms_last_update_qty`,`province`,`warehouse_classify`) AS STRING)) h FROM agents_scm_execute_detail_hourly_d) x GROUP BY b) n WHERE EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_execute_detail_hourly_d' AND NOT(v.fingerprint<=>o.calc_extra_json)) UNION ALL SELECT o.family,o.source,o.`role`,o.b,o.fingerprint FROM (SELECT calculation_scope family,source_order_no source,line_no `role`,CAST(numerator AS INT) b,calc_extra_json fingerprint FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state') o WHERE o.family='cancellation' AND o.source='agents_scm_execute_detail_hourly_d' AND o.`role`='groups' AND NOT(EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_execute_detail_hourly_d' AND NOT(v.fingerprint<=>o.calc_extra_json)))
UNION ALL
SELECT 'cancellation' family,'agents_scm_order_trace_final_di' source,'groups' `role`,n.b,n.fingerprint FROM (SELECT MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) AS b,CONCAT(CAST(COUNT(*) AS STRING),'/',CAST(SUM(CAST(CONV(SUBSTR(h,1,15),16,10) AS DECIMAL(38,0))) AS STRING),'/',CAST(SUM(CAST(CONV(SUBSTR(h,16,15),16,10) AS DECIMAL(38,0))) AS STRING)) AS fingerprint FROM (SELECT `cust_code` AS cust_code,MD5(CAST(JSON_ARRAY(`executeorderno`,`fromorderno`,`cust_code`,`cust_name`,`province`,`receive_wh`,`timeout_code`,`deliver_wh`,`lastshipmenttime`,`wms_order_close_time`,`wms_ship_status`,`load_time`,`need_qty_origin`,`createsource`,`load_status`,`latestsendcardate`,`province_region_name`,`region_name`,`update_time`) AS STRING)) h FROM agents_scm_order_trace_final_di) x GROUP BY b) n WHERE EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_order_trace_final_di' AND NOT(v.fingerprint<=>o.calc_extra_json)) UNION ALL SELECT o.family,o.source,o.`role`,o.b,o.fingerprint FROM (SELECT calculation_scope family,source_order_no source,line_no `role`,CAST(numerator AS INT) b,calc_extra_json fingerprint FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state') o WHERE o.family='cancellation' AND o.source='agents_scm_order_trace_final_di' AND o.`role`='groups' AND NOT(EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_order_trace_final_di' AND NOT(v.fingerprint<=>o.calc_extra_json)))
UNION ALL
SELECT 'cancellation' family,'dim_bas_warehouse' source,'warehouse' `role`,n.b,n.fingerprint FROM (SELECT b,SHA2(CONCAT('[',GROUP_CONCAT(CONCAT('{"b":',CAST(b AS STRING),',"k":',SUBSTRING(CAST(JSON_ARRAY(k) AS STRING),2,LENGTH(CAST(JSON_ARRAY(k) AS STRING))-2),',"v":',SUBSTRING(CAST(JSON_ARRAY(v) AS STRING),2,LENGTH(CAST(JSON_ARRAY(v) AS STRING))-2),',"p":',SUBSTRING(CAST(JSON_ARRAY(p) AS STRING),2,LENGTH(CAST(JSON_ARRAY(p) AS STRING))-2),'}'),',' ORDER BY k ASC NULLS FIRST,v ASC NULLS FIRST,p ASC NULLS FIRST),']'),256) AS fingerprint FROM (SELECT MOD(CRC32(COALESCE(CAST(k AS STRING),'')),4096) b,k,v,p FROM (SELECT DISTINCT warehouse_id k,warehouse_classify v,NULL p FROM dim_bas_warehouse) p) x GROUP BY b) n WHERE EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='dim_bas_warehouse' AND NOT(v.fingerprint<=>o.calc_extra_json)) UNION ALL SELECT o.family,o.source,o.`role`,o.b,o.fingerprint FROM (SELECT calculation_scope family,source_order_no source,line_no `role`,CAST(numerator AS INT) b,calc_extra_json fingerprint FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state') o WHERE o.family='cancellation' AND o.source='dim_bas_warehouse' AND o.`role`='warehouse' AND NOT(EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='dim_bas_warehouse' AND NOT(v.fingerprint<=>o.calc_extra_json)))
UNION ALL
SELECT 'cancellation' family,'agents_scm_material_in_out_summary_d' source,'warehouse' `role`,n.b,n.fingerprint FROM (SELECT b,SHA2(CONCAT('[',GROUP_CONCAT(CONCAT('{"b":',CAST(b AS STRING),',"k":',SUBSTRING(CAST(JSON_ARRAY(k) AS STRING),2,LENGTH(CAST(JSON_ARRAY(k) AS STRING))-2),',"v":',SUBSTRING(CAST(JSON_ARRAY(v) AS STRING),2,LENGTH(CAST(JSON_ARRAY(v) AS STRING))-2),',"p":',SUBSTRING(CAST(JSON_ARRAY(p) AS STRING),2,LENGTH(CAST(JSON_ARRAY(p) AS STRING))-2),'}'),',' ORDER BY k ASC NULLS FIRST,v ASC NULLS FIRST,p ASC NULLS FIRST),']'),256) AS fingerprint FROM (SELECT MOD(CRC32(COALESCE(CAST(k AS STRING),'')),4096) b,k,v,p FROM (SELECT DISTINCT warehouseid k,warehouse_classify v,pickup_point p FROM agents_scm_material_in_out_summary_d) p) x GROUP BY b) n WHERE EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_material_in_out_summary_d' AND NOT(v.fingerprint<=>o.calc_extra_json)) UNION ALL SELECT o.family,o.source,o.`role`,o.b,o.fingerprint FROM (SELECT calculation_scope family,source_order_no source,line_no `role`,CAST(numerator AS INT) b,calc_extra_json fingerprint FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type='sql_state') o WHERE o.family='cancellation' AND o.source='agents_scm_material_in_out_summary_d' AND o.`role`='warehouse' AND NOT(EXISTS(SELECT 1 FROM ai_db.order_kpi_ds_versions v LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_source_version' AND o.source_order_no=v.source WHERE v.phase='before' AND v.source='agents_scm_material_in_out_summary_d' AND NOT(v.fingerprint<=>o.calc_extra_json)));

-- 20_1_fingerprints
