iness.candidate_count AS `candidate_count`,raw_business.known_count AS `known_count`,raw_business.pending_count AS `pending_count`,raw_business.judgement_state AS `judgement_state`,raw_business.pending_reason_code AS `pending_reason_code`,raw_business.pending_reason_text AS `pending_reason_text`,raw_business.quantity_unit_code AS `quantity_unit_code`,raw_business.aggregation_rule_code AS `aggregation_rule_code`,raw_business.rule_version AS `rule_version`,raw_business.data_cutoff_time AS `data_cutoff_time`,raw_business.updated_at AS `updated_at`,raw_business.calc_extra_json AS `calc_extra_json` FROM (SELECT 'amendment' AS `metric_code`,'detail' AS `record_type`,SHA2(CAST(JSON_ARRAY(executeorderno,cust_code,cust_order_no,material_code,belong_base,duplicate_ordinal) AS STRING),256) AS `record_key`,'shared' AS `calculation_scope`,shipped_at AS `stat_time`,NULL AS `snapshot_date`,executeorderno AS `order_no`,cust_order_no AS `source_order_no`,NULL AS `line_no`,cust_code AS `customer_code`,material_code AS `sku_code`,belong_base AS `base_name`,pickup_point AS `pickup_point`,NULL AS `item_name`,NULL AS `category_name`,NULL AS `director_name`,region_name AS `region_name`,province_region_name AS `province_name`,NULL AS `sales_region`,CASE WHEN invalid=0 THEN changed_quantity ELSE 0 END AS `numerator`,effective_qty AS `denominator`,NULL AS `base_denominator`,1 AS `candidate_count`,1-invalid AS `known_count`,invalid AS `pending_count`,CASE WHEN invalid=0 THEN 'confirmed' ELSE 'pending' END AS `judgement_state`,CASE WHEN invalid>0 THEN 'ORIGINAL_AMENDMENT_INVALID' END AS `pending_reason_code`,NULL AS `pending_reason_text`,'商品数量' AS `quantity_unit_code`,'amendment-frozen-v1' AS `aggregation_rule_code`,145656960853753 AS `rule_version`,(SELECT data_cutoff_time FROM ai_db.order_kpi_ds_run) AS `data_cutoff_time`,(SELECT updated_at FROM ai_db.order_kpi_ds_run) AS `updated_at`,CAST(JSON_OBJECT('cust_name',cust_name,'header_addtime',CAST(header_addtime AS STRING),'change_order_qty',change_order_qty,'dms_last_update_qty',dms_last_update_qty,'need_qty_origin',need_qty_origin,'changed_quantity',changed_quantity) AS STRING) AS `calc_extra_json` FROM (SELECT *,CASE WHEN requested_qty>=0 AND requested_qty<effective_qty THEN effective_qty-requested_qty ELSE 0 END AS changed_quantity,CASE WHEN NULLIF(TRIM(cust_code),'') IS NULL OR NULLIF(TRIM(cust_order_no),'') IS NULL OR NULLIF(TRIM(material_code),'') IS NULL OR orderstatus IS NULL THEN 1 ELSE 0 END AS invalid,ROW_NUMBER() OVER(PARTITION BY executeorderno,cust_code,cust_order_no,material_code,belong_base ORDER BY shipped_at,header_addtime,change_order_qty,dms_last_update_qty,need_qty_origin) AS duplicate_ordinal FROM (SELECT s.cust_code,s.cust_order_no,s.executeorderno,s.belong_base,s.pickup_point,s.material_code,s.region_name,s.province_region_name,s.cust_name,s.header_addtime,s.shipped_at,s.orderstatus,s.detailstatus,s.is_stat,s.change_order_qty,s.dms_last_update_qty,s.need_qty_origin,s.warehouseid,s.receive_wh,s.createsource,s.is_virtual,s.timeout_code,s.order_close_time,s.is_short_transfer,
