    FROM (SELECT * FROM agents_scm_execute_detail_d WHERE MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='amendment')) d

    WHERE (''=''
      OR (''='郑州' AND d.pickup_point='01')
      OR (''<>'郑州' AND d.belong_base=''))
