stomer_code,IF(n.record_key IS NULL,o.sku_code,n.sku_code) AS sku_code,IF(n.record_key IS NULL,o.base_name,n.base_name) AS base_name,IF(n.record_key IS NULL,o.pickup_point,n.pickup_point) AS pickup_point,IF(n.record_key IS NULL,o.item_name,n.item_name) AS item_name,IF(n.record_key IS NULL,o.category_name,n.category_name) AS category_name,IF(n.record_key IS NULL,o.director_name,n.director_name) AS director_name,IF(n.record_key IS NULL,o.region_name,n.region_name) AS region_name,IF(n.record_key IS NULL,o.province_name,n.province_name) AS province_name,IF(n.record_key IS NULL,o.sales_region,n.sales_region) AS sales_region,IF(n.record_key IS NULL,o.numerator,n.numerator) AS numerator,IF(n.record_key IS NULL,o.denominator,n.denominator) AS denominator,IF(n.record_key IS NULL,o.base_denominator,n.base_denominator) AS base_denominator,IF(n.record_key IS NULL,o.candidate_count,n.candidate_count) AS candidate_count,IF(n.record_key IS NULL,o.known_count,n.known_count) AS known_count,IF(n.record_key IS NULL,o.pending_count,n.pending_count) AS pending_count,IF(n.record_key IS NULL,'__incremental_delete__',n.judgement_state) AS judgement_state,IF(n.record_key IS NULL,o.pending_reason_code,n.pending_reason_code) AS pending_reason_code,IF(n.record_key IS NULL,o.pending_reason_text,n.pending_reason_text) AS pending_reason_text,IF(n.record_key IS NULL,o.quantity_unit_code,n.quantity_unit_code) AS quantity_unit_code,IF(n.record_key IS NULL,o.aggregation_rule_code,n.aggregation_rule_code) AS aggregation_rule_code,IF(n.record_key IS NULL,o.rule_version,n.rule_version) AS rule_version,IF(n.record_key IS NULL,o.data_cutoff_time,n.data_cutoff_time) AS data_cutoff_time,IF(n.record_key IS NULL,o.updated_at,n.updated_at) AS updated_at,IF(n.record_key IS NULL,o.calc_extra_json,n.calc_extra_json) AS calc_extra_json FROM (SELECT raw_business.metric_code AS `metric_code`,raw_business.record_type AS `record_type`,raw_business.record_key AS `record_key`,raw_business.calculation_scope AS `calculati