 `sales_region`,n AS `numerator`,d AS `denominator`,NULL AS `base_denominator`,candidates AS `candidate_count`,candidates AS `known_count`,0 AS `pending_count`,'confirmed' AS `judgement_state`,NULL AS `pending_reason_code`,NULL AS `pending_reason_text`,'商品数量' AS `quantity_unit_code`,'fulfillment-frozen-v1' AS `aggregation_rule_code`,145656960853753 AS `rule_version`,(SELECT data_cutoff_time FROM ai_db.order_kpi_ds_run) AS `data_cutoff_time`,(SELECT updated_at FROM ai_db.order_kpi_ds_run) AS `updated_at`,NULL AS `calc_extra_json` FROM (SELECT CAST(period_end AS DATE) AS day,base,category,item,sku,cust_code,region,province,scope_kind,SUM(demand) AS d,SUM(demand-GREATEST(demand-LEAST(sent,demand),0)) AS n,COUNT(*) AS candidates FROM (SELECT m.*,g.region,g.province,CASE WHEN x.fromorderno IS NULL THEN 'shared' ELSE 'national_only' END AS scope_kind FROM (SELECT fromorderno,cust_code,new_material_code AS sku,
  MAX(belong_base) AS base,MAX(product_categ_name) AS category,MAX(pinxiang) AS item,
  MAX(new_material_name) AS name,SUM(need_qty_origin) AS demand,SUM(qtyshipped) AS sent,
  MAX(final_period) AS period_start,MAX(final_period) AS period_end,
  CASE WHEN COUNT(need_qty_origin)=COUNT(*) AND COUNT(qtyshipped)=COUNT(*)
