        MAX(fromorderno_month) OVER (PARTITION BY fromorderno,cust_code,new_material_code) AS product_period
      FROM (SELECT * FROM agents_order_execute_isontime_mi WHERE MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='fulfillment')) m
      WHERE exp_flag='否' AND (order_qty_origin>0 OR need_qty_origin>0)
        AND pickup_point_kpi IN ('郑州','华东','西南','华南','遂平')) observations
    WHERE (fromorderno_month=product_period OR fromorderno_month IS NULL)
      AND (''='' OR belong_base='')) cleaned
  GROUP BY fromorderno,cust_code,new_material_code) m LEFT JOIN (SELECT fromorderno,cust_code,new_material_code,
    CASE WHEN COUNT(NULLIF(TRIM(region_name),''))=COUNT(*) AND COUNT(DISTINCT NULLIF(TRIM(region_name),''))=1 THEN MAX(NULLIF(TRIM(region_name),'')) END AS region,CASE WHEN COUNT(NULLIF(TRIM(province_region_name),''))=COUNT(*) AND COUNT(DISTINCT NULLIF(TRIM(province_region_name),''))=1 THEN MAX(NULLIF(TRIM(province_region_name),'')) END AS province
    FROM (SELECT * FROM agents_order_execute_isontime_mi WHERE MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='fulfillment')) agents_order_execute_isontime_mi WHERE exp_flag='否' AND (order_qty_origin>0 OR need_qty_origin>0)
      AND pickup_point_kpi IN ('郑州','华东','西南','华南','遂平') AND (''='' OR belong_base='')
