    WHERE (fromorderno_month=product_period OR fromorderno_month IS NULL)
      AND (''='' OR belong_base='')) c GROUP BY fromorderno,cust_code,new_material_code HAVING COUNT(DISTINCT belong_base)>1) x ON x.fromorderno<=>m.fromorderno AND x.cust_code<=>m.cust_code AND x.new_material_code<=>m.sku UNION ALL SELECT m.*,g.region,g.province,'base_only' AS scope_kind FROM (SELECT fromorderno,cust_code,new_material_code AS sku,
