      FROM (SELECT * FROM agents_order_execute_isontime_mi WHERE MOD(CRC32(COALESCE(CAST(cust_code AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='fulfillment')) m
