 SELECT base,sku,signature,MIN(stock_date) AS valid_from,MAX(stock_date) AS valid_to,MAX(category) AS category,MAX(item) AS item,MAX(inventory) AS inventory,MAX(sales_plan) AS sales_plan,MAX(transfer_plan) AS transfer_plan,MAX(available) AS available,MAX(aged) AS aged,MAX(plan_month_offset) AS plan_month_offset,MAX(source_rows) AS source_rows,MAX(national_stock_records) AS national_stock_records,MAX(national_plan_records) AS national_plan_records,MAX(national_stock_invalid) AS national_stock_invalid,MAX(national_plan_invalid) AS national_plan_invalid,MAX(base_plan_invalid) AS base_plan_invalid,MAX(invalid) AS invalid,MAX(age_names) AS age_names,MAX(age_item) AS age_item,MAX(age_invalid) AS age_invalid,MAX(month_days) AS month_days,MAX(next_month_days) AS next_month_days,MAX(name) AS name FROM numbered GROUP BY base,sku,signature,run_id) q) raw_business) n FULL OUTER JOIN (SELECT * FROM ai_db.order_kpi_result_v1 WHERE metric_code='inventory' AND MOD(CRC32(COALESCE(CAST(sku_code AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='inventory')) o ON o.metric_code=n.metric_code AND o.record_type=n.record_type AND o.record_key=n.record_key WHERE (n.record_key IS NULL AND o.record_type<>'member_set') OR o.record_key IS NULL OR (n.record_key IS NOT NULL AND NOT (n.calculation_scope<=>o.calculation_scope AND n.stat_time<=>o.stat_time AND n.snapshot_date<=>o.snapshot_date AND n.order_no<=>o.order_no AND n.source_order_no<=>o.source_order_no AND n.line_no<=>o.line_no AND n.customer_code<=>o.customer_code AND n.sku_code<=>o.sku_code AND n.base_name<=>o.base_name AND n.pickup_point<=>o.pickup_point AND n.item_name<=>o.item_name AND n.category_name<=>o.category_name AND n.director_name<=>o.director_name AND n.region_name<=>o.region_name AND n.province_name<=>o.province_name AND n.sales_region<=>o.sales_region AND n.numerator<=>o.numerator AND n.denominator<=>o.denominator AND n.base_denominator<=>o.base_denominator AND n.candidate_count<=>o.candidate_co