    AND COUNT(DISTINCT t.requireddeliverytimebak)=1 AND COUNT(DISTINCT t.requireddeliverytime)=1
    AND COUNT(DISTINCT t.expected_deliv_time)=1
    THEN CASE WHEN MIN(CASE WHEN LOWER(TRIM(t.cust_type)) IN ('kamd','dc') THEN 1 ELSE 0 END)=1
    THEN GREATEST(MAX(t.requireddeliverytimebak),MAX(t.requireddeliverytime),MAX(CAST(t.expected_deliv_time AS DATETIME))) + INTERVAL '18' HOUR
    ELSE GREATEST(MAX(t.requireddeliverytimebak),MAX(t.requireddeliverytime),MAX(CAST(t.expected_deliv_time AS DATETIME))) + INTERVAL '12' HOUR END END AS deadline,
  CASE WHEN COUNT(t.requireddeliverytimebak)=COUNT(*) AND COUNT(t.requireddeliverytime)=COUNT(*)
    AND COUNT(DISTINCT t.requireddeliverytimebak)=1 AND COUNT(DISTINCT t.requireddeliverytime)=1
    THEN CASE WHEN MIN(CASE WHEN LOWER(TRIM(t.cust_type)) IN ('kamd','dc') THEN 1 ELSE 0 END)=1
    THEN GREATEST(MAX(t.requireddeliverytimebak),MAX(t.requireddeliverytime)) + INTERVAL '18' HOUR
    ELSE GREATEST(MAX(t.requireddeliverytimebak),MAX(t.requireddeliverytime)) + INTERVAL '12' HOUR END END AS known_deadline,
  CASE WHEN COUNT(DISTINCT CASE WHEN LOWER(TRIM(t.cust_type)) IN ('kamd','dc') THEN 1 ELSE 0 END)>1 THEN 1
    ELSE MAX(CASE WHEN (CASE
  WHEN NULLIF(TRIM(t.receive_wh),'') IS NULL THEN 0
  WHEN f.warehouse_classify NOT IN ('01','02') OR r.warehouse_classify NOT IN ('01','02') THEN 0
  WHEN f.warehouse_classify IN ('01','02') AND r.warehouse_classify IN ('01','02')
    AND f.pickup_point IS NOT NULL AND r.pickup_point IS NOT NULL
    THEN CASE WHEN f.pickup_point=r.pickup_point THEN 1 ELSE 0 END
  ELSE NULL END) IS NULL THEN 1 ELSE 0 END) END AS invalid_scope
  FROM (SELECT * FROM agents_scm_order_trace_final_di WHERE MOD(CRC32(COALESCE(CAST(executeorderno AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) t INNER JOIN
    (SELECT history.executeorderno,history.cust_code,MAX(history.update_time) AS updated
      FROM (SELECT * FROM agents_scm_order_trace_final_di WHERE MOD(CRC32(COALESCE(CAST(executeorderno AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) history INNER JOIN
        (SELECT DISTINCT executeorderno,cust_code FROM (SELECT * FROM agents_scm_order_trace_final_di WHERE MOD(CRC32(COALESCE(CAST(executeorderno AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) agents_scm_order_trace_final_di
          WHERE COALESCE(gpsisinraildate_to,arriveconfirm_time)>=(SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.start') FROM ai_db.order_kpi_ds_run)
            AND COALESCE(gpsisinraildate_to,arriveconfirm_time)<(SELECT data_cutoff_time FROM ai_db.order_kpi_ds_run)) candidates
        ON candidates.executeorderno=history.executeorderno AND candidates.cust_code=history.cust_code
      GROUP BY history.executeorderno,history.cust_code) latest
    ON latest.executeorderno=t.executeorderno AND latest.cust_code=t.cust_code AND latest.updated=t.update_time
  LEFT JOIN (SELECT warehouseid,
  CASE WHEN COUNT(DISTINCT NULLIF(TRIM(pickup_point),''))=1
    THEN MAX(NULLIF(TRIM(pickup_point),'')) END AS pickup_point,
  CASE WHEN COUNT(DISTINCT NULLIF(TRIM(warehouse_classify),''))=1
    THEN MAX(NULLIF(TRIM(warehouse_classify),'')) END AS warehouse_classify
  FROM (SELECT warehouseid,pickup_point,warehouse_classify FROM agents_scm_material_in_out_summary_d
    UNION ALL SELECT warehouse_id AS warehouseid,NULL AS pickup_point,warehouse_classify FROM dim_bas_warehouse) sources
  GROUP BY warehouseid) f ON f.warehouseid=t.deliver_wh
  LEFT JOIN (SELECT warehouseid,
  CASE WHEN COUNT(DISTINCT NULLIF(TRIM(pickup_point),''))=1
    THEN MAX(NULLIF(TRIM(pickup_point),'')) END AS pickup_point,
  CASE WHEN COUNT(DISTINCT NULLIF(TRIM(warehouse_classify),''))=1
    THEN MAX(NULLIF(TRIM(warehouse_classify),'')) END AS warehouse_classify
  FROM (SELECT warehouseid,pickup_point,warehouse_classify FROM agents_scm_material_in_out_summary_d
    UNION ALL SELECT warehouse_id AS warehouseid,NULL AS pickup_point,warehouse_classify FROM dim_bas_warehouse) sources
  GROUP BY warehouseid) r ON r.warehouseid=t.receive_wh
  GROUP BY t.executeorderno,t.cust_code HAVING MAX(CASE WHEN TRIM(t.is_dispatch)='否'
  OR TRIM(t.region_name) IN ('海外大区','国外大区','港澳大区')
  OR TRIM(t.is_virtual_odo) IN ('1','2')
  OR COALESCE(TRIM(t.vehicle_type),'')=''
  OR REPLACE(REPLACE(TRIM(t.vehicle_type_name),'(', '（'),')','）')
    IN ('铁柜40','铁柜45','无车型要求（常温）','无车型要求（速冻）','自提')
  OR TRIM(t.timeout_code) IN ('14','16','安全库存','调账订单')
  OR (CASE
  WHEN NULLIF(TRIM(t.receive_wh),'') IS NULL THEN 0
  WHEN f.warehouse_classify NOT IN ('01','02') OR r.warehouse_classify NOT IN ('01','02') THEN 0
  WHEN f.warehouse_classify IN ('01','02') AND r.warehouse_classify IN ('01','02')
    AND f.pickup_point IS NOT NULL AND r.pickup_point IS NOT NULL
    THEN CASE WHEN f.pickup_point=r.pickup_point THEN 1 ELSE 0 END
  ELSE NULL END)=1 THEN 1 ELSE 0 END)=0),ontime_arrivals AS (SELECT t.executeorderno,t.cust_code,t.arrived AS arrival_date,t.region,t.province,
    CASE WHEN t.invalid_scope=0 AND t.arrived<t.known_deadline THEN 1
      WHEN t.deadline IS NOT NULL AND t.invalid_scope=0 THEN CASE WHEN t.arrived<t.deadline THEN 1 ELSE 0 END END AS ontime,
    CASE WHEN t.invalid_scope>0 OR (t.deadline IS NULL AND (t.known_deadline IS NULL OR t.arrived>=t.known_deadline)) THEN 1 ELSE 0 END AS invalid
    FROM ontime_traces t WHERE t.arrived>=(SELECT JSON_EXTRACT_STRING(calc_extra_json,'$.start') FROM ai_db.order_kpi_ds_run) AND t.arrived<(SELECT data_cutoff_time FROM ai_db.order_kpi_ds_run)),ontime_products AS (SELECT cust_order_no,cust_code,material_code,executeorderno,
  belong_base,detailstatus,
  CASE WHEN COUNT(DISTINCT NULLIF(TRIM(product_item),''))=1 THEN MAX(NULLIF(TRIM(product_item),'')) END AS product_item,
  MAX(CASE WHEN is_virtual IN (1,2) THEN 1 ELSE 0 END) AS virtual_excluded
  FROM (SELECT cust_order_no,cust_code,material_code,executeorderno,
  belong_base,detailstatus,is_stat,product_item,is_virtual FROM (SELECT * FROM agents_scm_execute_detail_hourly_d WHERE MOD(CRC32(COALESCE(CAST(executeorderno AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) agents_scm_execute_detail_hourly_d
  WHERE (''='' OR belong_base='')
  UNION ALL SELECT d.cust_order_no,d.cust_code,d.material_code,d.executeorderno,
    d.belong_base,d.detailstatus,d.is_stat,d.product_item,d.is_virtual FROM (SELECT * FROM agents_scm_execute_detail_d WHERE MOD(CRC32(COALESCE(CAST(executeorderno AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) d LEFT JOIN
  (SELECT DISTINCT cust_code,cust_order_no,executeorderno,belong_base,1 AS header_present
   FROM (SELECT * FROM agents_scm_execute_detail_hourly_d WHERE MOD(CRC32(COALESCE(CAST(executeorderno AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) agents_scm_execute_detail_hourly_d) seen ON (CASE WHEN seen.cust_code IS NULL THEN 'N' ELSE CONCAT('V',seen.cust_code) END)=(CASE WHEN d.cust_code IS NULL THEN 'N' ELSE CONCAT('V',d.cust_code) END) AND (CASE WHEN seen.cust_order_no IS NULL THEN 'N' ELSE CONCAT('V',seen.cust_order_no) END)=(CASE WHEN d.cust_order_no IS NULL THEN 'N' ELSE CONCAT('V',d.cust_order_no) END) AND (CASE WHEN seen.executeorderno IS NULL THEN 'N' ELSE CONCAT('V',seen.executeorderno) END)=(CASE WHEN d.executeorderno IS NULL THEN 'N' ELSE CONCAT('V',d.executeorderno) END) AND (CASE WHEN seen.belong_base IS NULL THEN 'N' ELSE CONCAT('V',seen.belong_base) END)=(CASE WHEN d.belong_base IS NULL THEN 'N' ELSE CONCAT('V',d.belong_base) END)
  WHERE (''='' OR d.belong_base='') AND seen.header_present IS NULL) execution_rows
  WHERE executeorderno IN (SELECT executeorderno FROM ontime_arrivals) AND (''='' OR belong_base='')
  GROUP BY cust_order_no,cust_code,material_code,executeorderno,belong_base,detailstatus) SELECT DISTINCT h.executeorderno AS order_no,h.cust_code AS customer,a.arrival_date,a.ontime,a.invalid,
 h.belong_base AS base,d.product_categ_name AS category,h.product_item AS item,h.material_code AS sku,a.region,a.province FROM ontime_products h INNER JOIN ontime_arrivals a
    ON a.executeorderno=h.executeorderno AND a.cust_code=h.cust_code
    INNER JOIN (SELECT executeorderno,cust_code,belong_base FROM ontime_products GROUP BY executeorderno,cust_code,belong_base
      HAVING MAX(virtual_excluded)=0) eligible ON eligible.executeorderno=h.executeorderno AND eligible.cust_code=h.cust_code AND eligible.belong_base<=>h.belong_base
    LEFT JOIN (SELECT material_code,CASE WHEN COUNT(DISTINCT product_categ_name)=1 THEN MAX(product_categ_name) END AS product_categ_name
      FROM agents_scm_material_in_out_summary_d GROUP BY material_code) d ON d.material_code=h.material_code) b),execution_sets AS (SELECT order_no,scope_kind,CASE WHEN scope_kind='base' THEN base ELSE NULL END AS selected_base,MIN(arrival_date) AS first_arrival,MAX(arrival_date) AS last_arrival,
 ARRAY_SORT(ARRAY_DISTINCT(ARRAY_AGG(CAST(JSON_ARRAY(customer,CAST(arrival_date AS STRING),CAST(ontime AS STRING),CAST(invalid AS STRING),base,category,item,sku,region,province) AS STRING)))) AS members FROM members GROUP BY order_no,scope_kind,CASE WHEN scope_kind='base' THEN base ELSE NULL END)
 SELECT *,SHA2(CONCAT('[',ARRAY_JOIN(members,','),']'),256) AS member_key FROM execution_sets) q) raw_business) n FULL OUTER JOIN (SELECT * FROM ai_db.order_kpi_result_v1 WHERE (metric_code='ontime' AND record_type='execution' AND MOD(CRC32(COALESCE(CAST(order_no AS STRING),'')),4096) IN (SELECT b FROM ai_db.order_kpi_ds_dirty WHERE family='ontime')) OR (metric_code='ontime' AND record_type='member_set')) o ON o.metric_code=n.metric_code AND o.record_type=n.record_type AND o.record_key=n.record_key WHERE (n.record_key IS NULL AND o.record_type<>'member_set') OR o.record_key IS NULL OR (n.record_key IS NOT NULL AND NOT (n.calculation_scope<=>o.calculation_scope AND n.stat_time<=>o.stat_time AND n.snapshot_date<=>o.snapshot_date AND n.order_no<=>o.order_no AND n.source_order_no<=>o.source_order_no AND n.line_no<=>o.line_no AND n.customer_code<=>o.customer_code AND n.sku_code<=>o.sku_code AND n.base_name<=>o.base_name AND n.pickup_point<=>o.pickup_point AND n.item_name<=>o.item_name AND n.category_name<=>o.category_name AND n.director_name<=>o.director_name AND n.region_name<=>o.region_name AND n.province_name<=>o.province_name AND n.sales_region<=>o.sales_region AND n.numerator<=>o.numerator AND n.denominator<=>o.denominator AND n.base_denominator<=>o.base_denominator AND n.candidate_count<=>o.candidate_count AND n.known_count<=>o.known_count AND n.pending_count<=>o.pending_count AND n.judgement_state<=>o.judgement_state AND n.pending_reason_code<=>o.pending_reason_code AND n.pending_reason_text<=>o.pending_reason_text AND n.quantity_unit_code<=>o.quantity_unit_code AND n.aggregation_rule_code<=>o.aggregation_rule_code AND n.rule_version<=>o.rule_version AND n.calc_extra_json<=>o.calc_extra_json));

-- 50_member_cleanup
INSERT INTO ai_db.order_kpi_ds_delta (metric_code,record_type,record_key,calculation_scope,stat_time,snapshot_date,order_no,source_order_no,line_no,customer_code,sku_code,base_name,pickup_point,item_name,category_name,director_name,region_name,province_name,sales_region,numerator,denominator,base_denominator,candidate_count,known_count,pending_count,judgement_state,pending_reason_code,pending_reason_text,quantity_unit_code,aggregation_rule_code,rule_version,data_cutoff_time,updated_at,calc_extra_json) SELECT s.metric_code,s.record_type,s.record_key,s.calculation_scope,s.stat_time,s.snapshot_date,s.order_no,s.source_order_no,s.line_no,s.customer_code,s.sku_code,s.base_name,s.pickup_point,s.item_name,s.category_name,s.director_name,s.region_name,s.province_name,s.sales_region,s.numerator,s.denominator,s.base_denominator,s.candidate_count,s.known_count,s.pending_count,'__incremental_delete__',s.pending_reason_code,s.pending_reason_text,s.quantity_unit_code,s.aggregation_rule_code,s.rule_version,s.data_cutoff_time,s.updated_at,s.calc_extra_json FROM ai_db.order_kpi_result_v1 s INNER JOIN (SELECT DISTINCT e.aggregation_rule_code k FROM ai_db.order_kpi_result_v1 e INNER JOIN ai_db.order_kpi_ds_delta d ON e.metric_code=d.metric_code AND e.record_type=d.record_type AND e.record_key=d.record_key WHERE e.metric_code='ontime' AND e.record_type='execution') a ON a.k=s.record_key LEFT ANTI JOIN (SELECT e.aggregation_rule_code k FROM ai_db.order_kpi_result_v1 e LEFT ANTI JOIN ai_db.order_kpi_ds_delta d ON e.metric_code=d.metric_code AND e.record_type=d.record_type AND e.record_key=d.record_key WHERE e.metric_code='ontime' AND e.record_type='execution' UNION ALL SELECT aggregation_rule_code FROM ai_db.order_kpi_ds_delta WHERE metric_code='ontime' AND record_type='execution' AND NOT(judgement_state<=>'__incremental_delete__')) b ON b.k=s.record_key WHERE s.metric_code='ontime' AND s.record_type='member_set';

