INSERT INTO ai_db.order_kpi_ds_delta (metric_code,record_type,record_key,calculation_scope,stat_time,snapshot_date,order_no,source_order_no,line_no,customer_code,sku_code,base_name,pickup_point,item_name,category_name,director_name,region_name,province_name,sales_region,numerator,denominator,base_denominator,candidate_count,known_count,pending_count,judgement_state,pending_reason_code,pending_reason_text,quantity_unit_code,aggregation_rule_code,rule_version,data_cutoff_time,updated_at,calc_extra_json) SELECT 'metadata' AS `metric_code`,'sql_state' AS `record_type`,SHA2(CONCAT_WS('/',s.family,s.source,s.`role`,CAST(s.b AS STRING)),256) AS `record_key`,s.family AS `calculation_scope`,NULL AS `stat_time`,NULL AS `snapshot_date`,NULL AS `order_no`,s.source AS `source_order_no`,s.`role` AS `line_no`,NULL AS `customer_code`,NULL AS `sku_code`,NULL AS `base_name`,NULL AS `pickup_point`,NULL AS `item_name`,NULL AS `category_name`,NULL AS `director_name`,NULL AS `region_name`,NULL AS `province_name`,NULL AS `sales_region`,CAST(s.b AS DECIMAL(38,12)) AS `numerator`,CAST(NULL AS DECIMAL(38,12)) AS `denominator`,CAST(NULL AS DECIMAL(38,12)) AS `base_denominator`,NULL AS `candidate_count`,NULL AS `known_count`,NULL AS `pending_count`,NULL AS `judgement_state`,NULL AS `pending_reason_code`,NULL AS `pending_reason_text`,NULL AS `quantity_unit_code`,NULL AS `aggregation_rule_code`,145656960853753 AS `rule_version`,NULL AS `data_cutoff_time`,(SELECT updated_at FROM ai_db.order_kpi_ds_run) AS `updated_at`,s.fingerprint AS `calc_extra_json` FROM ai_db.order_kpi_ds_scan s LEFT JOIN ai_db.order_kpi_result_v1 o ON o.metric_code='metadata' AND o.record_type='sql_state' AND o.record_key=SHA2(CONCAT_WS('/',s.family,s.source,s.`role`,CAST(s.b AS STRING)),256) WHERE o.record_key IS NULL OR NOT(s.fingerprint<=>o.calc_extra_json) UNION ALL SELECT o.metric_code,o.record_type,o.record_key,o.calculation_scope,o.stat_time,o.snapshot_date,o.order_no,o.source_order_no,o.line_no,o.customer_code,o.sku_code,o.base_name,o.pickup_point,o.item_name,o.category_name,o.director_name,o.region_name,o.province_name,o.sales_region,o.numerator,o.denominator,o.base_denominator,o.candidate_count,o.known_count,o.pending_count,'__incremental_delete__',o.pending_reason_code,o.pending_reason_text,o.quantity_unit_code,o.aggregation_rule_code,o.rule_version,o.data_cutoff_time,o.updated_at,o.calc_extra_json FROM ai_db.order_kpi_result_v1 o LEFT ANTI JOIN ai_db.order_kpi_ds_scan s ON o.record_key=SHA2(CONCAT_WS('/',s.family,s.source,s.`role`,CAST(s.b AS STRING)),256) WHERE o.metric_code='metadata' AND o.record_type='sql_state' UNION ALL SELECT metric_code,record_type,record_key,calculation_scope,stat_time,snapshot_date,order_no,source_order_no,line_no,customer_code,sku_code,base_name,pickup_point,item_name,category_name,director_name,region_name,province_name,sales_region,numerator,denominator,base_denominator,candidate_count,known_count,pending_count,'__incremental_delete__',pending_reason_code,pending_reason_text,quantity_unit_code,aggregation_rule_code,rule_version,data_cutoff_time,updated_at,calc_extra_json FROM ai_db.order_kpi_result_v1 WHERE metric_code='metadata' AND record_type IN ('incremental_state','sql_bootstrap');

